    T={'1':np.ones_like(t),'C':np.cos(w*t),'S':np.sin(w*t),'C2':np.cos(2*w*t),'S2':np.sin(2*w*t)}
    P={'1':np.ones_like(t),'x':x,'v':v,'v2':v*v,'v3':v**3,'x2':x*x,'xv':x*v,'1/v':1/v,'x/v':x/v}
