    M=np.column_stack(cols)
    c=np.linalg.lstsq(M,a,rcond=None)[0]
    print(w,'NMSE',np.mean((M@c-a)**2)/np.var(a))
    if w==0.313208411451037:
        nm=[pk+'*'+tk for tk in T for pk in P]
        for n,cc in zip(nm,c):
            if abs(cc)>0.03: print(n,round(cc,4))
